t['page'] ?>.</p><div class="form-actions"><?php if($audit['page']>1): ?><a class="button" href="/robo/system/log?q=<?= urlencode($search) ?>&page=<?= (int)$audit['page']-1 ?>">Předchozí</a><?php endif; ?><?php if($audit['page']*$audit['per_page']<$audit['total']): ?><a class="button" href="/robo/system/log?q=<?= urlencode($search) ?>&page=<?= (int)$audit['page']+1 ?>">Další</a><?php endif; ?></div></section>
